const deals = $node["HubSpot Search Deals"].json.results || [];
const assoc = $json.results || [];
const map = {};
for (const a of assoc) { const from=a.from?.id; const to=(a.to||[])[0]?.toObjectId; if(from) map[from]=to||null; }
return deals.map(d => ({ json: {
  Deal_ID: d.id,
  hs_lastmodifieddate: d.properties?.hs_lastmodifieddate ?? null,
  _synced_at: new Date().toISOString(),
  _raw: JSON.stringify({ properties: d.properties, associations: { contacts: { results: map[d.id] ? [{ id: String(map[d.id]) }] : [] } } })
}}));
